import { Component, createSignal, For, Setter } from "solid-js";

import { Button } from "#core/ui-next/components/button.jsx";
import { Flipbook, TextureAtlas } from "#core/ui-next/components/flipbook.jsx";
import { Header } from "#core/ui-next/components/header.jsx";
import { ScrollArea } from "#core/ui-next/components/scroll-area.jsx";
import { BoundNumber } from "#core/ui-next/sandbox/components-browser/components/bound-property.jsx";
import { TextInput } from "#core/ui-next/sandbox/components-browser/components/text-input.jsx";
import { createArraySignal } from "#core/ui-next/utilities/solid-utilities.js";

export const FlipbookExample: Component = () => {
	const [fps, setFps] = createSignal(30);
	const [atlas, useAtlas] = createArraySignal<TextureAtlas>([
		{ src: "blp:hourglasses01", spriteHeight: 128, spriteWidth: 128, size: 512, nFrames: 16 },
		{ src: "blp:hourglasses02", spriteHeight: 128, spriteWidth: 128, size: 512, nFrames: 16 },
		{ src: "blp:hourglasses03", spriteHeight: 128, spriteWidth: 128, size: 1024, nFrames: 13 },
	]);

	return (
		<div class="flex flex-row flex-auto mx-4">
			<ScrollArea class="w-1\/3 m-2 p-2 border border-secondary-3">
				<BoundNumber
					name="fps"
					signal={[fps, setFps as Setter<number | undefined>]}
				/>
				<For each={atlas()}>
					{(entry, index) => (
						<>
							<div class="my-2 flex flex-col">
								<div class="text-center">src</div>
								<div class="relative h-10">
									<TextInput
										class="flex-grow w-full absolute"
										value={entry.src}
										onInput={(e) => {
											entry.src = e.currentTarget.value;
											useAtlas((a) => a);
										}}
									/>
								</div>
							</div>
							<div class="my-2 flex flex-col">
								<div class="text-center">spriteHeight</div>
								<div class="relative h-10">
									<TextInput
										class="flex-grow w-full absolute"
										type="number"
										value={entry.spriteHeight}
										onInput={(e) => {
											entry.spriteHeight = Number(e.currentTarget.value);
											useAtlas((a) => a);
										}}
									/>
								</div>
							</div>
							<div class="my-2 flex flex-col">
								<div class="text-center">spriteWidth</div>
								<div class="relative h-10">
									<TextInput
										class="flex-grow w-full absolute"
										type="number"
										value={entry.spriteWidth}
										onInput={(e) => {
											entry.spriteWidth = Number(e.currentTarget.value);
											useAtlas((a) => a);
										}}
									/>
								</div>
							</div>
							<div class="my-2 flex flex-col">
								<div class="text-center">size</div>
								<div class="relative h-10">
									<TextInput
										class="flex-grow w-full absolute"
										type="number"
										value={entry.size}
										onInput={(e) => {
											entry.size = Number(e.currentTarget.value);
											useAtlas((a) => a);
										}}
									/>
								</div>
							</div>
							<div class="my-2 flex flex-col">
								<div class="text-center">size</div>
								<div class="relative h-10">
									<TextInput
										class="flex-grow w-full absolute"
										type="number"
										value={entry.nFrames}
										onInput={(e) => {
											entry.nFrames = Number(e.currentTarget.value);
											useAtlas((a) => a);
										}}
									/>
								</div>
							</div>
							<Button
								class="mb-4"
								onClick={() => useAtlas((a) => a.splice(index(), 1))}
							>
								Remove Atlas {index()}
							</Button>
						</>
					)}
				</For>
				<Button
					class="mb-4"
					onClick={() =>
						useAtlas((a) =>
							a.push({
								src: "blp:hourglasses01",
								spriteHeight: 128,
								spriteWidth: 128,
								size: 512,
								nFrames: 16,
							}),
						)
					}
				>
					Add Atlas {atlas().length}
				</Button>
			</ScrollArea>
			<div class="w-2\/3 m-2 p-2 border border-secondary-3 flex flex-col justify-center items-center">
				<div class="flex flex-col my-4 items-center">
					<Header class="text-2xl">Flipbook</Header>
					<Flipbook
						fps={fps()}
						atlas={atlas()}
						class="size-48"
					/>
				</div>
				<div class="flex flex-col my-4 items-center">
					<Header class="text-2xl">Flipbook.Hourglass</Header>
					<Flipbook.Hourglass class="size-48" />
				</div>
			</div>
		</div>
	);
};
